const ustawienia = { motyw: "jasny", jezyk: "pl", powiadomienia: false };
console.log(Object.entries(ustawienia));
// [['motyw', 'jasny'], ['jezyk', 'pl'], ['powiadomienia', false]]

const ustawienia = { motyw: "jasny", jezyk: "pl" };
const mapa = new Map(Object.entries(ustawienia));
console.log(mapa.get("motyw")); // "jasny"

const cennik = { chleb: 4.5, mleko: 3.2, maslo: 8.0 };
const nowyCennik = Object.fromEntries(
  Object.entries(cennik).map(([k, v]) => [k, Number((v * 1.1).toFixed(2))])
);
console.log(nowyCennik); // { chleb: 4.95, mleko: 3.52, maslo: 8.8 }

const domyslne = { rozmiar: "M", kolor: "czarny" };
const wybor = { kolor: "bialy" };
const wynik = Object.assign({}, domyslne, wybor);
console.log(wynik); // { rozmiar: 'M', kolor: 'bialy' }
console.log(domyslne); // { rozmiar: 'M', kolor: 'czarny' } - NIEZMIENIONY

const stale = Object.freeze({ PI: 3.14, E: 2.71 });
stale.PI = 100;
console.log(stale.PI); // 3.14 - bez zmian

const defaults = { timeout: 5000, debug: false };
const overrides = { debug: true };

Object.assign(defaults, overrides);
console.log(defaults); // { timeout: 5000, debug: true } - ZMUTOWANY, mimo braku bezposredniego przypisania

const oceny = { Jan: 4, Ala: 5, Kuba: 3 };
const dobre = Object.entries(oceny).filter(([imie, ocena]) => ocena >= 4);
console.log(dobre); // [['Jan', 4], ['Ala', 5]]

const magazyn = { jablka: 50, banany: 30, gruszki: 20 };
const suma = Object.values(magazyn).reduce((s, i) => s + i, 0);
console.log(suma); // 100

const produkty = { A: 100, B: 200, C: 50 };
const posortowane = Object.entries(produkty).sort((a, b) => b[1] - a[1]);
console.log(posortowane); // [['B', 200], ['A', 100], ['C', 50]]

const ustawienia = { motyw: "ciemny", jezyk: "en" };
Object.keys(ustawienia).forEach(k => {
  console.log(`${k}: ${ustawienia[k]}`);
});
// motyw: ciemny
// jezyk: en

const uzytkownicy = [{ imie: "Jan" }, { imie: "Ala" }];
Object.assign(uzytkownicy[0], { aktywny: true });
console.log(uzytkownicy[0]); // { imie: 'Jan', aktywny: true }

const ceny = { maly: 10, sredni: 15, duzy: 20 };
const opisy = Object.entries(ceny).map(([k, v]) => `${k}: ${v} zl`);
console.log(opisy); // ['maly: 10 zl', 'sredni: 15 zl', 'duzy: 20 zl']

const a = { x: 1 };
const b = { y: 2 };
const c = { z: 3 };
const polaczone = Object.assign({}, a, b, c);
console.log(polaczone); // { x: 1, y: 2, z: 3 }

function policzWlasciwosci(obiekt) {
  return Object.keys(obiekt).length;
}

console.log(policzWlasciwosci({ a: 1, b: 2, c: 3 })); // 3
console.log(policzWlasciwosci({})); // 0

const statystyki = { wygrane: 10, przegrane: 5, remisy: 2 };
const wynik = Object.entries(statystyki).find(([k, v]) => v > 8);
console.log(wynik); // ['wygrane', 10]

const obiekt = { a: "pierwszy", b: "drugi" };
const klucze = Object.keys(obiekt);
const wartosci = Object.values(obiekt);

console.log(klucze[0], wartosci[0]); // "a" "pierwszy" - ta sama pozycja, ta sama para

const pary = [["jeden", 1], ["dwa", 2]];
const obiekt = Object.fromEntries(pary);
const rozszerzony = { ...obiekt, trzy: 3 };
console.log(rozszerzony); // { jeden: 1, dwa: 2, trzy: 3 }

const punkty = { Ala: 100, Bartek: 85, Celina: 120 };
const top2 = Object.entries(punkty)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 2)
  .map(([imie]) => imie);

console.log(top2); // ['Celina', 'Ala']

const a = { ustawienia: { x: 1 } };
const b = { ustawienia: { y: 2 } };
const polaczone = Object.assign({}, a, b);

console.log(polaczone.ustawienia); // { y: 2 } - CALKOWICIE nadpisane, x zniknelo (plytkie polaczenie)

function mapujWartosci(obiekt, fn) {
  return Object.fromEntries(
    Object.entries(obiekt).map(([k, v]) => [k, fn(v)])
  );
}

console.log(mapujWartosci({ a: 1, b: 2 }, n => n * 100)); // { a: 100, b: 200 }

const osoba = { imie: "Jan", wiek: 30 };
const wszystkieWypelnione = Object.values(osoba).every(v => v !== undefined && v !== null && v !== "");
console.log(wszystkieWypelnione); // true

const dane = { a: 1, b: 2, c: 3, d: 4 };
const parzyste = Object.fromEntries(
  Object.entries(dane).filter(([k, v]) => v % 2 === 0)
);
console.log(parzyste); // { b: 2, d: 4 }

const zamowienie = { produkt: "Laptop", ilosc: 2, cena: 3000 };
const podsumowanie = Object.entries(zamowienie).reduce((acc, [k, v], i) => {
  return acc + (i > 0 ? "; " : "") + `${k}=${v}`;
}, "");

console.log(podsumowanie); // "produkt=Laptop; ilosc=2; cena=3000"

const ankieta1 = { jakosc: 8, cena: 6 };
const ankieta2 = { jakosc: 9, obsluga: 7 };
const wszystkieKlucze = [...new Set([...Object.keys(ankieta1), ...Object.keys(ankieta2)])];
console.log(wszystkieKlucze); // ['jakosc', 'cena', 'obsluga']

